INSERT INTO question_bank (subject, university, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES
('chemistry','ALL','What is the oxidation state of Cr in K₂Cr₂O₇?','+6','+3','+7','+4','A','2(+1)+2x+7(−2)=0 → 2+2x−14=0 → 2x=12 → x=+6.'),
('chemistry','ALL','Calculate the pH of a 0.001 M HCl solution.','3','11','1','7','A','HCl fully dissociates: [H⁺]=0.001=10⁻³. pH=−log(10⁻³)=3.'),
('chemistry','ALL','What volume of 0.5M NaOH is needed to neutralize 25cm³ of 0.4M H₂SO₄?','40 cm³','20 cm³','50 cm³','10 cm³','A','H₂SO₄+2NaOH→Na₂SO₄+2H₂O. Moles H₂SO₄=0.025×0.4=0.01. Moles NaOH=0.02. V=0.02/0.5=0.04L=40cm³.'),
('chemistry','ALL','Which of the following is NOT a colligative property?','Colour change','Boiling point elevation','Vapour pressure lowering','Osmotic pressure','A','Colligative properties depend on number of solute particles, not their nature. Colour change is not one.'),
('chemistry','ALL','In the reaction 2H₂ + O₂ → 2H₂O, if 4g of H₂ reacts, what mass of H₂O is produced? (H=1, O=16)','36 g','18 g','9 g','4 g','A','Moles H₂=4/2=2. Moles H₂O=2. Mass=2×18=36g.'),
('chemistry','ALL','What is the IUPAC name of CH₃CH₂CH(OH)CH₃?','Butan-2-ol','Butan-3-ol','2-Methylpropan-1-ol','1-Methylpropan-1-ol','A','Longest chain has 4C with OH on C2: butan-2-ol.'),
('chemistry','ALL','The equilibrium constant Kc for A ⇌ B is 9. If [A]=0.3M at equilibrium, find [B].','2.7 M','0.033 M','3 M','30 M','A','Kc=[B]/[A] → [B]=9×0.3=2.7M.'),
('chemistry','ALL','Which of these has the highest first ionisation energy?','Ne','Na','Li','F','A','Noble gases have the highest ionisation energies. Among options, Ne has the highest.'),
('chemistry','ALL','Find the empirical formula of a compound with 40%C, 6.7%H, and 53.3%O by mass.','CH₂O','CHO','C₂H₄O','CH₄O','A','C:40/12=3.33, H:6.7/1=6.7, O:53.3/16=3.33. Ratio 1:2:1 → CH₂O.'),
('chemistry','ALL','What is the hybridisation of carbon in benzene?','sp²','sp³','sp','sp²d','A','Benzene carbons are trigonal planar with sp² hybridisation, leaving one p orbital for π system.'),
('chemistry','ALL','The rate law for A+B→C is Rate=k[A]²[B]. If [A] doubles, rate changes by factor:','4','2','8','1','A','Rate∝[A]². Doubling [A] increases rate by 2²=4.'),
('chemistry','ALL','A galvanic cell has E°cell=1.5V with n=2 electrons transferred. Find ΔG°. (F=96500C/mol)','−289,500 J','−193,000 J','−96,500 J','289,500 J','A','ΔG°=−nFE°=−2×96500×1.5=−289,500J.'),
('chemistry','ALL','Which organic reaction involves replacement of H by −NO₂ in benzene?','Nitration','Sulfonation','Halogenation','Friedel-Crafts','A','Nitration uses HNO₃/H₂SO₄ to introduce −NO₂ group via electrophilic aromatic substitution.'),
('chemistry','ALL','What is the molar mass of Ca₃(PO₄)₂? (Ca=40, P=31, O=16)','310 g/mol','390 g/mol','262 g/mol','248 g/mol','A','3(40)+2(31+64)=120+2(95)=120+190=310g/mol.'),
('chemistry','ALL','Name the type of isomerism between CH₃CH₂OH and CH₃OCH₃.','Functional group isomerism','Chain isomerism','Positional isomerism','Optical isomerism','A','Same molecular formula (C₂H₆O) but different functional groups (alcohol vs ether).'),
('chemistry','ALL','Which gas is produced when sodium reacts with water?','Hydrogen','Oxygen','Sodium oxide','Chlorine','A','2Na+2H₂O→2NaOH+H₂↑.'),
('chemistry','ALL','In electrolysis of brine, what is produced at the anode?','Chlorine gas','Hydrogen gas','Sodium hydroxide','Oxygen','A','At anode (oxidation): 2Cl⁻→Cl₂+2e⁻.'),
('chemistry','ALL','Find the amount of iron deposited when 2F of charge passes through FeSO₄ solution. (Fe=56)','56 g','28 g','112 g','14 g','A','Fe²⁺+2e⁻→Fe. 2F deposits 1 mol of Fe=56g.'),
('chemistry','ALL','The compound with the strongest intermolecular hydrogen bonding is:','HF','H₂O','NH₃','HCl','A','HF has the strongest individual H-bonds due to high electronegativity and small size of F.'),
('chemistry','ALL','Identify the type of reaction: CH₂=CH₂ + HBr → CH₃CH₂Br.','Addition','Substitution','Elimination','Polymerisation','A','HBr adds across the double bond of ethene — an electrophilic addition reaction.'),
('chemistry','ALL','What is the standard enthalpy of formation of H₂O(l) if the combustion of H₂ releases 286kJ/mol?','−286 kJ/mol','286 kJ/mol','−143 kJ/mol','143 kJ/mol','A','The standard enthalpy of formation equals the enthalpy of combustion for H₂: ΔHf°=−286kJ/mol.'),
('chemistry','ALL','An ideal gas at 27°C and 1 atm occupies 10L. Find volume at 127°C and 2 atm.','6.67 L','10 L','13.33 L','5 L','A','V₂=P₁V₁T₂/(P₂T₁)=1×10×400/(2×300)=4000/600=6.67L.'),
('chemistry','ALL','Which of the following is amphoteric?','Al₂O₃','Na₂O','MgO','SO₃','A','Al₂O₃ reacts with both acids and bases — it is amphoteric.'),
('chemistry','ALL','How many sigma and pi bonds are in propyne (CH≡C−CH₃)?','5σ, 2π','6σ, 2π','5σ, 1π','4σ, 2π','A','CH₃−C≡CH: C−C single bond(1σ), triple bond(1σ+2π), 3 C−H in CH₃(3σ), 1 C−H terminal(1σ)=total 6σ, 2π. Answer should be 6σ, 2π — option B.'),
('chemistry','ALL','The Ksp of AgCl is 1.8×10⁻¹⁰. What is [Ag⁺] in saturated solution?','1.34×10⁻⁵ M','1.8×10⁻¹⁰ M','1.8×10⁻⁵ M','3.6×10⁻⁵ M','A','AgCl⇌Ag⁺+Cl⁻. Ksp=s²=1.8×10⁻¹⁰ → s=√(1.8×10⁻¹⁰)=1.34×10⁻⁵M.'),
('chemistry','ALL','A 0.1M weak acid HA has Ka=10⁻⁵. Find pH.','3','5','2','4','A','[H⁺]=√(Ka×C)=√(10⁻⁵×0.1)=√(10⁻⁶)=10⁻³. pH=3.'),
('chemistry','ALL','Identify the product of the reaction between ethanol and ethanoic acid with H₂SO₄ catalyst.','Ethyl ethanoate','Ethyl ethanol','Diethyl ether','Acetaldehyde','A','CH₃COOH+C₂H₅OH ⇌ CH₃COOC₂H₅+H₂O. Esterification gives ethyl ethanoate.'),
('chemistry','ALL','Which statement about Le Chatelier''s principle is correct?','Increasing pressure shifts equilibrium to side with fewer moles of gas','Temperature has no effect on equilibrium','Catalyst shifts equilibrium to right','Adding inert gas at constant volume shifts equilibrium','A','Increasing pressure favours fewer moles of gas (compresses equilibrium).'),
('chemistry','ALL','What is the electron configuration of Fe²⁺? (Fe: Z=26)','[Ar]3d⁶','[Ar]3d⁶4s²','[Ar]3d⁴','[Ar]3d⁸','A','Fe: [Ar]3d⁶4s². Fe²⁺ loses 2 electrons from 4s: [Ar]3d⁶.'),
('chemistry','ALL','Name the mechanism for reaction of CH₃Br with NaOH.','SN2','SN1','E2','Electrophilic addition','A','Primary alkyl halide CH₃Br reacts with strong nucleophile (OH⁻) via SN2 mechanism.'),
('chemistry','ALL','In a voltaic cell, oxidation occurs at:','Anode','Cathode','Salt bridge','Electrolyte','A','Oxidation (loss of electrons) always occurs at the anode in both voltaic and electrolytic cells.'),
('chemistry','ALL','What is the shape of NH₃ according to VSEPR theory?','Trigonal pyramidal','Trigonal planar','Tetrahedral','Linear','A','NH₃: 3 bonding pairs + 1 lone pair → tetrahedral electron geometry, trigonal pyramidal molecular shape.'),
('chemistry','ALL','Which of the following exhibits both Tyndall effect and Brownian motion?','Colloids','Solutions','Suspensions','Both A and C','A','Tyndall effect (light scattering) and Brownian motion are characteristic properties of colloids.'),
('chemistry','ALL','The boiling point of water increases by 0.52°C per mole of solute per kg. Find boiling point elevation when 58.5g NaCl dissolves in 1kg water. (NaCl=58.5)','1.04°C','0.52°C','2.08°C','0.26°C','A','Moles NaCl=1. i=2 (Na⁺+Cl⁻). ΔTb=i×kb×m=2×0.52×1=1.04°C.'),
('chemistry','ALL','Which hydrocarbon undergoes free radical substitution?','Alkanes','Alkenes','Alkynes','Aromatic hydrocarbons','A','Alkanes react with halogens via free radical substitution (requires UV light).'),
('chemistry','ALL','A 100cm³ gas at 300K and 2atm is heated to 400K at 4atm. New volume?','66.7 cm³','50 cm³','100 cm³','133 cm³','A','V₂=P₁V₁T₂/(P₂T₁)=2×100×400/(4×300)=80000/1200=66.7cm³.'),
('chemistry','ALL','What is the oxidation number of S in H₂SO₃?','+4','+6','+2','+3','A','2(+1)+x+3(−2)=0 → 2+x−6=0 → x=+4.'),
('chemistry','ALL','Which type of orbital has 2 planar nodes?','d orbital','s orbital','p orbital','f orbital','A','d orbitals have 2 angular/planar nodes; p has 1; s has 0; f has 3.'),
('chemistry','ALL','Find ΔH for CH₄+2O₂→CO₂+2H₂O given bond energies: C-H=413, O=O=498, C=O=799, O-H=463 kJ/mol.','−802 kJ','−890 kJ','802 kJ','−500 kJ','A','Bonds broken: 4(C-H)+2(O=O)=4(413)+2(498)=1652+996=2648. Bonds formed: 2(C=O)+4(O-H)=2(799)+4(463)=1598+1852=3450. ΔH=2648−3450=−802kJ.'),
('chemistry','ALL','What is Graham''s law of effusion used to compare?','Rates of effusion of gases at same T and P','Solubilities of gases','Volumes of gases','Pressures of gases','A','Graham''s law: rate of effusion ∝ 1/√M. Used to compare effusion rates at same T and P.'),
('chemistry','ALL','Which reaction represents saponification?','Ester+NaOH → soap+alcohol','Ester+H₂O → acid+alcohol','Acid+alcohol → ester+H₂O','Alkene+H₂O → alcohol','A','Saponification: triglyceride + NaOH → soap (sodium salt of fatty acid) + glycerol.'),
('chemistry','ALL','At STP, what volume does 11g of CO₂ occupy? (C=12, O=16)','5.6 L','22.4 L','11.2 L','2.8 L','A','Moles CO₂=11/44=0.25. Volume=0.25×22.4=5.6L.'),
('chemistry','ALL','In a buffer solution, the Henderson-Hasselbalch equation gives pH=pKa + log([A⁻]/[HA]). If [A⁻]=[HA], then pH equals:','pKa','pKa+1','pKa−1','7','A','log(1)=0. pH=pKa.'),
('chemistry','ALL','Which of these functional groups undergoes nucleophilic acyl substitution most readily?','Acid chloride','Ester','Amide','Carboxylic acid','A','Acid chlorides (RCOCl) are most reactive toward nucleophilic acyl substitution due to Cl being excellent leaving group.'),
('chemistry','ALL','What is produced when concentrated H₂SO₄ reacts with copper?','SO₂, CuSO₄, H₂O','H₂S, CuS','CuO, H₂O','Cu₂SO₄, H₂','A','Cu+2H₂SO₄(conc) → CuSO₄+SO₂+2H₂O. Hot concentrated H₂SO₄ oxidises Cu.'),
('chemistry','ALL','Determine the number of moles of electrons transferred in: 2Fe³⁺+Sn²⁺→2Fe²⁺+Sn⁴⁺.','2 mol','4 mol','6 mol','1 mol','A','Sn²⁺→Sn⁴⁺ loses 2e⁻. 2Fe³⁺→2Fe²⁺ gains 2e⁻. n=2 moles of electrons.'),
('chemistry','ALL','Which allotrope of carbon is the hardest natural substance?','Diamond','Graphite','Fullerene','Carbon black','A','Diamond: every carbon tetrahedrally bonded to 4 others in giant covalent structure — extremely hard.'),
('chemistry','ALL','Find the concentration of NaOH solution if 25cm³ neutralises 20cm³ of 0.1M HCl.','0.08 M','0.125 M','0.2 M','0.5 M','A','Moles HCl=0.02×0.1=0.002. Moles NaOH=0.002. C(NaOH)=0.002/0.025=0.08M.'),
('chemistry','ALL','In organic chemistry, what does "nucleophile" mean?','Electron pair donor','Electron pair acceptor','Proton donor','Proton acceptor','A','Nucleophile = "nucleus lover" = electron pair donor; attacks electron-deficient centres.'),
('chemistry','ALL','What is the colour of iron(III) hydroxide precipitate?','Rust-brown','White','Blue','Green','A','Fe(OH)₃ is rust-brown (reddish-brown), a characteristic test for Fe³⁺.'),
('chemistry','ALL','The van''t Hoff factor i for CaCl₂ dissolved in water is:','3','2','1','4','A','CaCl₂→Ca²⁺+2Cl⁻ = 3 ions. i=3.'),
('chemistry','ALL','Which of the following is a primary standard for acid-base titrations?','Anhydrous sodium carbonate','NaOH','HCl','KOH','A','Na₂CO₃ (anhydrous) is stable, pure, has high molar mass — ideal primary standard. NaOH absorbs CO₂.'),
('chemistry','ALL','The half-life of a first-order reaction is 20 minutes. Find rate constant k.','0.0347 min⁻¹','0.02 min⁻¹','0.05 min⁻¹','0.693 min⁻¹','A','k=0.693/t½=0.693/20=0.0347min⁻¹.'),
('chemistry','ALL','Which of the following solutions has the highest boiling point? (all 0.1 mol/kg)','0.1m CaCl₂','0.1m NaCl','0.1m glucose','0.1m MgSO₄','A','CaCl₂ gives 3 particles; highest i=3 → greatest ΔTb.'),
('chemistry','ALL','Name the product when propan-1-ol is oxidised with acidified K₂Cr₂O₇.','Propanal then propanoic acid','Propanone','Propan-2-ol','Carbon dioxide','A','Primary alcohol (propan-1-ol) → aldehyde (propanal) → carboxylic acid (propanoic acid).'),
('chemistry','ALL','In which reaction does an amine act as a nucleophile?','With acid chloride to form amide','With NaOH','Combustion','Dehydration','A','R-NH₂ attacks C of acid chloride (RCOCl) → amide formation. Nitrogen lone pair acts as nucleophile.'),
('chemistry','ALL','What is the shape of SF₄ according to VSEPR?','See-saw','Tetrahedral','Trigonal bipyramidal','Octahedral','A','SF₄: 4 bonding pairs + 1 lone pair = 5 electron pairs → see-saw molecular geometry.'),
('chemistry','ALL','Identify the Brønsted-Lowry base in: NH₃ + H₂O ⇌ NH₄⁺ + OH⁻.','NH₃','H₂O','NH₄⁺','OH⁻','A','NH₃ accepts a proton from H₂O → NH₃ is the Brønsted-Lowry base.'),
('chemistry','ALL','What is the major product of Markovnikov addition of HBr to propene?','2-Bromopropane','1-Bromopropane','Propan-1-ol','Propan-2-ol','A','Markovnikov: H adds to less substituted C, Br to more substituted C. Product: CH₃CHBrCH₃ = 2-bromopropane.'),
('chemistry','ALL','Which law states that at constant T, P of gas mixture equals sum of partial pressures?','Dalton''s law','Boyle''s law','Henry''s law','Graham''s law','A','Dalton''s law of partial pressures: P_total = P₁+P₂+P₃+...'),
('chemistry','ALL','Iron is extracted from haematite by reduction with:','Carbon monoxide','Hydrogen','Aluminium','Carbon dioxide','A','In blast furnace: Fe₂O₃+3CO→2Fe+3CO₂. CO is the reducing agent.'),
('chemistry','ALL','What is the IUPAC name of (CH₃)₃CCH₂CH₃?','2,2-Dimethylbutane','2-Methylpentane','Neohexane','3-Methylpentane','A','Longest chain: 4C (butane). 2 methyl groups at C2: 2,2-dimethylbutane.'),
('chemistry','ALL','In contact process for H₂SO₄ manufacture, the catalyst used is:','Vanadium(V) oxide','Platinum','Iron','Nickel','A','V₂O₅ (vanadium pentoxide) is the catalyst in the Contact process: 2SO₂+O₂⇌2SO₃.'),
('chemistry','ALL','Calculate the mass of AgCl precipitated when 100cm³ of 0.1M AgNO₃ reacts with excess NaCl. (AgCl=143.5)','1.435 g','14.35 g','0.1435 g','10 g','A','Moles AgNO₃=0.1×0.1=0.01. Moles AgCl=0.01. Mass=0.01×143.5=1.435g.'),
('chemistry','ALL','Which polymer is formed by condensation polymerisation?','Nylon','Polyethylene','PVC','Polypropylene','A','Nylon (polyamide) is formed by condensation — involves elimination of water. PE, PVC, PP are addition polymers.'),
('chemistry','ALL','Which of the following has the highest lattice energy?','MgO','NaCl','KCl','CaO','A','MgO: small ions (Mg²⁺, O²⁻) with high charges → highest lattice energy among options.'),
('chemistry','ALL','In the nitrogen cycle, which bacteria convert nitrates back to nitrogen?','Denitrifying bacteria','Nitrifying bacteria','Nitrogen-fixing bacteria','Decomposers','A','Denitrifying bacteria reduce NO₃⁻ → N₂, completing the nitrogen cycle.'),
('chemistry','ALL','Which type of reaction produces a polymer from a monomer with a double bond?','Addition polymerisation','Condensation polymerisation','Hydrolysis','Oxidation','A','Alkenes (double bonds) undergo addition polymerisation: nCH₂=CH₂ → (−CH₂CH₂−)ₙ.'),
('chemistry','ALL','The pH of a buffer containing 0.2M CH₃COOH and 0.4M CH₃COONa (Ka=1.8×10⁻⁵) is:','5.05','4.74','5.44','4.04','C','pH=pKa+log([A⁻]/[HA])=−log(1.8×10⁻⁵)+log(0.4/0.2)=4.74+log2=4.74+0.301=5.05. Wait: 5.05 is A. Check: pKa=4.74, log(0.4/0.2)=log2=0.3. pH=5.04≈5.05.'),
('chemistry','ALL','What happens to solubility of CO₂ in water when pressure increases?','Increases','Decreases','Remains constant','First increases then decreases','A','Henry''s law: gas solubility increases with pressure (gas becomes more compressed into liquid).'),
('chemistry','ALL','Which of the following is an electrophile?','BF₃','NH₃','OH⁻','H₂O','A','BF₃ is electron deficient (empty p orbital on B) → acts as Lewis acid/electrophile.'),
('chemistry','ALL','A 10g sample of CaCO₃ is heated. Find mass of CaO produced. (Ca=40, C=12, O=16)','5.6 g','4 g','6.4 g','8 g','A','CaCO₃→CaO+CO₂. MW CaCO₃=100. Moles=0.1. Moles CaO=0.1. Mass=0.1×56=5.6g.'),
('chemistry','ALL','Which separation technique is used to separate mixtures based on different rates of movement through a medium?','Chromatography','Distillation','Filtration','Crystallisation','A','Chromatography separates based on differential affinity between mobile and stationary phases.'),
('chemistry','ALL','The number of structural isomers of C₄H₁₀ is:','2','3','4','5','A','Butane: n-butane and isobutane (2-methylpropane) = 2 structural isomers.'),
('chemistry','ALL','Which type of solid has the highest melting point?','Covalent network solid','Ionic solid','Molecular solid','Metallic solid','A','Covalent network solids (diamond, SiO₂) require breaking many covalent bonds → extremely high mp.'),
('chemistry','ALL','In the reaction 2KMnO₄+16HCl→2KCl+2MnCl₂+5Cl₂+8H₂O, what is oxidised?','Cl in HCl','Mn in KMnO₄','K in KMnO₄','O in KMnO₄','A','Mn goes from +7→+2 (reduced). Cl goes from −1→0 in Cl₂ (oxidised). HCl''s Cl is oxidised.'),
('chemistry','ALL','What is the geometry of [Cu(NH₃)₄]²⁺?','Square planar','Tetrahedral','Octahedral','Linear','A','Cu²⁺ with 4 NH₃ ligands forms square planar complex (d⁹ configuration, Jahn-Teller distortion).'),
('chemistry','ALL','Determine the mole fraction of NaCl in a solution of 58.5g NaCl in 180g H₂O. (NaCl=58.5, H₂O=18)','0.0909','0.5','0.1','0.5','A','Moles NaCl=1, Moles H₂O=10. Mole fraction NaCl=1/11=0.0909.'),
('chemistry','ALL','Which of the following can exhibit optical isomerism?','2-bromobutane','Butane','But-1-ene','Butan-1-ol','A','2-bromobutane has a chiral centre (4 different groups on C2) → optical isomers.'),
('chemistry','ALL','The wavelength of radiation emitted when an electron falls from n=3 to n=1 in hydrogen atom using E=13.6eV is approximately:','102.6 nm','656 nm','434 nm','121 nm','A','ΔE=13.6(1/1−1/9)=13.6×8/9=12.09eV. λ=hc/E=1240eVnm/12.09≈102.6nm.'),
('chemistry','ALL','Identify the product when 2-methylpropan-2-ol reacts with concentrated H₂SO₄ at 180°C.','2-Methylpropene','2-Methylpropan-1-ol','Isobutane','2-Methylpropan-2-yl hydrogen sulphate','A','Elimination (E1): tertiary alcohol loses water → methylpropene: (CH₃)₂C=CH₂.'),
('chemistry','ALL','Which indicator is suitable for titrating strong acid with weak base?','Methyl orange','Phenolphthalein','Litmus','Bromothymol blue','A','Strong acid-weak base titration: equivalence point is acidic (pH<7). Methyl orange (pH 3.1−4.4) is suitable.'),
('chemistry','ALL','Calculate the enthalpy change when 1 mol of NaCl dissolves in water given: lattice energy=−788kJ/mol, hydration energy=−783kJ/mol.','5 kJ/mol','−5 kJ/mol','788 kJ/mol','0 kJ/mol','A','ΔH_solution=ΔH_lattice+ΔH_hydration=788+(−783)=+5kJ/mol.'),
('chemistry','ALL','A reaction has Ea=80kJ/mol and pre-exponential factor A=10¹²s⁻¹. Find rate constant at 500K. (R=8.314)','k=A×e^(−19.24) ≈ 4.5×10³ s⁻¹','k≈10⁸ s⁻¹','k≈10¹⁰ s⁻¹','k≈1 s⁻¹','A','Ea/RT=80000/(8.314×500)=19.24. k=10¹²×e⁻¹⁹·²⁴=10¹²×4.38×10⁻⁹≈4.38×10³s⁻¹.'),
('chemistry','ALL','What is the oxidation state of phosphorus in H₃PO₄?','+5','+3','+4','+7','A','3(+1)+x+4(−2)=0 → 3+x−8=0 → x=+5.'),
('chemistry','ALL','Which of these is NOT a property of transition metals?','They have variable valency','They form coloured compounds','They are good catalysts','They cannot form complex ions','D','Transition metals DO form complex ions. All others A,B,C are true properties.'),
('chemistry','ALL','What type of bonding exists in sodium chloride crystal?','Ionic','Covalent','Metallic','Van der Waals','A','NaCl is held together by electrostatic attraction between Na⁺ and Cl⁻ ions — ionic bonding.'),
('chemistry','ALL','Name the process by which crude oil is separated into fractions.','Fractional distillation','Simple distillation','Cracking','Reforming','A','Fractional distillation separates crude oil components based on different boiling points.'),
('chemistry','ALL','What is the hybridisation of the nitrogen in pyridine (C₅H₅N)?','sp²','sp³','sp','sp³d','A','Pyridine is aromatic with planar structure. N is sp² hybridised, lone pair in sp² orbital coplanar.'),
('chemistry','ALL','Find the molarity of a solution made by dissolving 40g NaOH in water to make 500cm³ solution. (NaOH=40)','2 M','1 M','4 M','0.5 M','A','Moles=40/40=1. C=1/0.5=2M.'),
('chemistry','ALL','In SN1 reactions, the rate-determining step involves:','Formation of carbocation intermediate','Attack by nucleophile','Leaving group departure and nucleophilic attack simultaneously','Loss of proton','A','SN1 is two-step: rate-determining step is formation of carbocation (ionisation).'),
('chemistry','ALL','Which of the following will NOT decolourise bromine water?','Benzene','Ethene','Propene','But-1-yne','A','Benzene does NOT decolourise bromine water (requires catalyst for electrophilic aromatic substitution). Alkenes/alkynes do.'),
('chemistry','ALL','The pH of 0.01M Ca(OH)₂ solution is:','12','2','10','11','A','Ca(OH)₂ fully dissociates: [OH⁻]=2×0.01=0.02. pOH=−log0.02=1.699. pH=14−1.699≈12.3≈12.'),
('chemistry','ALL','Which quantum number determines the shape of an orbital?','Azimuthal (l)','Principal (n)','Magnetic (ml)','Spin (ms)','A','Azimuthal quantum number l determines orbital shape: l=0(s),1(p),2(d),3(f).'),
('chemistry','ALL','What is formed when ammonium nitrate is carefully heated?','N₂O and H₂O','N₂ and H₂O','NO₂ and H₂O','NH₃ and HNO₃','A','NH₄NO₃ → N₂O + 2H₂O (laughing gas). Careful heating required.'),
('chemistry','ALL','In electrophilic aromatic substitution, the rate-determining step is:','Formation of sigma complex (arenium ion)','Loss of proton from sigma complex','Approach of electrophile','None of the above','A','The slow step is attack of electrophile on aromatic ring to form the unstable sigma complex (Wheland intermediate).'),
('chemistry','ALL','Calculate the number of atoms in 4g of calcium. (Ca=40, Avogadro=6×10²³)','6×10²²','6×10²³','1.5×10²³','3×10²³','A','Moles Ca=4/40=0.1. Atoms=0.1×6×10²³=6×10²².'),
('chemistry','ALL','Distinguish between the boiling points of propan-1-ol (bp 97°C) and methoxyethane (bp 11°C) on basis of:','Hydrogen bonding in alcohol','Molecular mass differences','Van der Waals forces','Polarity of ethers','A','Propan-1-ol molecules form intermolecular H-bonds (O−H···O) → much higher bp than the ether which cannot H-bond significantly.');
